\begin{tikzpicture}
\begin{axis}[
    width=0.70\textwidth,
    height=0.50\textwidth,
    xmin=-1.4, xmax=1.4,
    ymin=-0.2, ymax=1.8,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-1,0,1},
    ytick=\empty,
    axis equal image,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[very thick, domain=-1.25:1.25, samples=200] {x^2};

% horizontal tangent at origin
\addplot[thick, dashed, domain=-0.75:0.75, samples=2] {0};

% points and arrows along motion
\addplot[only marks, mark=*] coordinates {(0,0)};
\draw[->, thick] (axis cs:-0.95,0.9025) -- (axis cs:-0.65,0.4225);
\draw[->, thick] (axis cs:0.35,0.1225) -- (axis cs:0.70,0.49);

\node[anchor=south east] at (axis cs:0,0) {\(t=0\)};
\node[align=center, fill=white, inner sep=2pt] at (axis cs:0,1.32) {%
  \(x=t^3,\;y=t^6\)\\
  same curve: \(y=x^2\)\\
  but speed \(=0\) at the origin%
};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.68\textwidth,
    height=0.52\textwidth,
    xmin=-0.85, xmax=3.4,
    ymin=-1.75, ymax=1.75,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={0,1,2},
    ytick={-1,0,1},
    axis equal image,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
% original circle: thick semitransparent boundary only
\addplot[
    draw=blue!75!black,
    draw opacity=0.7,
    line width=4.2pt,
    domain=-1.5707963:1.5707963,
    samples=220
]
    ({2*cos(deg(x))*cos(deg(x))},{2*cos(deg(x))*sin(deg(x))});

% retracing interval: black dashes on top for contrast
\addplot[very thick, black, dashed, dash pattern=on 7pt off 5pt, domain=1.5707963:4.712389, samples=220]
    ({2*cos(deg(x))*cos(deg(x))},{2*cos(deg(x))*sin(deg(x))});

\addplot[only marks, mark=*] coordinates {(0,0) (2,0) (1,0)};
\node[anchor=south] at (axis cs:1,0) {center};
\node[anchor=west] at (axis cs:2.18,0.72) {\(r=2\cos\theta\)};
\node[anchor=west] at (axis cs:2.18,0.42) {dashed part retraces};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=\textwidth,
    xmin=-0.15, xmax=1.15,
    ymin=-1.15, ymax=1.15,
    axis lines=middle,
    xtick={0,1},
    ytick={-1,0,1},
    axis equal image,
    title={\(P_1(t)=(t^2,t^3)\)},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[very thick, domain=-1:1, samples=220] ({x^2},{x^3});
\addplot[thick, dashed, domain=0:0.75, samples=2] {0};
\addplot[only marks, mark=*] coordinates {(0,0)};
\node[anchor=west] at (axis cs:0.15,0.2) {\(\text{horizontal}\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=\textwidth,
    xmin=-1.15, xmax=1.15,
    ymin=-0.15, ymax=1.15,
    axis lines=middle,
    xtick={-1,0,1},
    ytick={0,1},
    axis equal image,
    title={\(P_2(t)=(t^3,t^2)\)},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[very thick, domain=-1:1, samples=220] ({x^3},{x^2});
\draw[thick, dashed] (axis cs:0,0) -- (axis cs:0,0.8);
\addplot[only marks, mark=*] coordinates {(0,0)};
\node[anchor=west] at (axis cs:0.12,0.55) {\(\text{vertical}\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=\textwidth,
    xmin=-0.15, xmax=1.15,
    ymin=-0.15, ymax=1.15,
    axis lines=middle,
    xtick={0,1},
    ytick={0,1},
    axis equal image,
    title={\(P_3(t)=(t^2,t^2)\)},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[very thick, domain=-1:1, samples=220] ({x^2},{x^2});
\addplot[thick, dashed, domain=0:0.85, samples=2] {x};
